import * as THREE from "three";

export interface DirectorInput {
  progress: number;
  pointerX: number;
  pointerY: number;
  elapsed: number;
  reducedMotion: boolean;
}

export interface DirectedState {
  cameraPosition: THREE.Vector3;
  cameraTarget: THREE.Vector3;
  assembly: number;
  reveal: number;
  membrane: number;
  signal: number;
  resolve: number;
  pointerDriftX: number;
  pointerDriftY: number;
}

const clamp01 = (value: number): number => Math.min(1, Math.max(0, value));
const smooth = (a: number, b: number, value: number): number => {
  const t = clamp01((value - a) / Math.max(0.0001, b - a));
  return t * t * (3 - 2 * t);
};

export class ExperienceDirector {
  private readonly camera = new THREE.Vector3();
  private readonly target = new THREE.Vector3();
  private readonly state: DirectedState = {
    cameraPosition: this.camera,
    cameraTarget: this.target,
    assembly: 0,
    reveal: 0,
    membrane: 0,
    signal: 0,
    resolve: 0,
    pointerDriftX: 0,
    pointerDriftY: 0,
  };

  public evaluate(input: DirectorInput): DirectedState {
    const p = clamp01(input.progress);
    const reveal = smooth(0.04, 0.24, p);
    const assembly = smooth(0.31, 0.61, p);
    const resolve = smooth(0.72, 0.91, p);
    const timeBreath = input.reducedMotion ? 0 : Math.sin(input.elapsed * 0.42) * 0.035;
    const pointerScale = input.reducedMotion ? 0 : 0.16 * (1 - resolve * 0.7);

    this.camera.set(
      THREE.MathUtils.lerp(1.45, 0.18, reveal) - assembly * 0.38 + resolve * 0.08 + input.pointerX * pointerScale,
      THREE.MathUtils.lerp(0.52, 0.08, assembly) + timeBreath + input.pointerY * pointerScale * 0.55,
      THREE.MathUtils.lerp(6.8, 5.45, assembly) + resolve * 0.18,
    );
    this.target.set(resolve * 0.12, -0.03, 0);

    this.state.assembly = assembly;
    this.state.reveal = reveal;
    this.state.membrane = smooth(0.18, 0.53, p) * (1 - resolve * 0.18);
    this.state.signal = smooth(0.36, 0.69, p);
    this.state.resolve = resolve;
    this.state.pointerDriftX = input.pointerX * pointerScale;
    this.state.pointerDriftY = input.pointerY * pointerScale;
    return this.state;
  }
}

import * as THREE from "three";
import type { DirectedState } from "./director";

export interface SceneOptions {
  canvas: HTMLCanvasElement;
  width: number;
  height: number;
  dpr: number;
  quality: string;
  reducedMotion: boolean;
}

interface DisposableMaterial extends THREE.Material {
  map?: THREE.Texture | null;
}

const PRODUCT_URI = "/creative-assets/acoustic-resonance-instrument-v1.png";

export class AcousticScene {
  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene = new THREE.Scene();
  private readonly camera = new THREE.PerspectiveCamera(34, 1, 0.1, 40);
  private readonly root = new THREE.Group();
  private readonly productGroup = new THREE.Group();
  private readonly productMaterial: THREE.MeshBasicMaterial;
  private readonly productPlane: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
  private readonly fallback: THREE.Group;
  private readonly rings: THREE.Mesh<THREE.RingGeometry, THREE.MeshBasicMaterial>[] = [];
  private readonly shards: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>[] = [];
  private readonly signal: THREE.LineSegments<THREE.BufferGeometry, THREE.LineBasicMaterial>;
  private productTexture: THREE.Texture | null = null;
  private textureRequest: THREE.Texture | null = null;
  private assetReady = false;
  private disposed = false;
  private viewportWidth = 1;
  private viewportHeight = 1;
  private mobile = false;

  public constructor(options: SceneOptions) {
    this.renderer = new THREE.WebGLRenderer({
      canvas: options.canvas,
      alpha: true,
      antialias: options.quality !== "low",
      powerPreference: options.quality === "low" ? "low-power" : "high-performance",
    });
    this.renderer.setClearColor(0x071017, 0);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;
    this.scene.fog = new THREE.FogExp2(0x071017, 0.075);
    this.scene.add(this.root);

    this.productMaterial = new THREE.MeshBasicMaterial({
      color: 0xf1fbfc,
      transparent: true,
      opacity: 0,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    this.productPlane = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), this.productMaterial);
    this.productPlane.renderOrder = 4;
    this.productGroup.add(this.productPlane);
    this.root.add(this.productGroup);

    this.fallback = this.createFallback();
    this.productGroup.add(this.fallback);

    const ringMaterial = new THREE.MeshBasicMaterial({
      color: 0x75d9ef,
      transparent: true,
      opacity: 0.15,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    for (let index = 0; index < 5; index += 1) {
      const ring = new THREE.Mesh(
        new THREE.RingGeometry(1.05 + index * 0.34, 1.065 + index * 0.34, 96),
        ringMaterial.clone(),
      );
      ring.position.set(0.44, -0.04, -0.18 - index * 0.045);
      ring.rotation.y = -0.16;
      this.rings.push(ring);
      this.root.add(ring);
    }

    const shardMaterial = new THREE.MeshBasicMaterial({
      color: 0x9bdae5,
      transparent: true,
      opacity: 0.12,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    for (let index = 0; index < 9; index += 1) {
      const shard = new THREE.Mesh(new THREE.PlaneGeometry(0.025, 0.72 + (index % 3) * 0.28), shardMaterial.clone());
      const angle = (index / 9) * Math.PI * 2;
      shard.position.set(Math.cos(angle) * 2.25 + 0.4, Math.sin(angle) * 1.42, -0.5);
      shard.rotation.z = angle;
      this.shards.push(shard);
      this.root.add(shard);
    }

    const signalPositions: number[] = [];
    const segmentCount = options.quality === "low" ? 34 : 70;
    for (let index = 0; index < segmentCount; index += 1) {
      const x = -3.4 + (index / segmentCount) * 6.8;
      const nextX = -3.4 + ((index + 1) / segmentCount) * 6.8;
      signalPositions.push(x, 0, -0.7, nextX, 0, -0.7);
    }
    const signalGeometry = new THREE.BufferGeometry();
    signalGeometry.setAttribute("position", new THREE.Float32BufferAttribute(signalPositions, 3));
    this.signal = new THREE.LineSegments(
      signalGeometry,
      new THREE.LineBasicMaterial({ color: 0x80e7f4, transparent: true, opacity: 0 }),
    );
    this.root.add(this.signal);

    this.loadProductTexture();
    this.resize(options.width, options.height, options.dpr, options.quality);
  }

  private createFallback(): THREE.Group {
    const group = new THREE.Group();
    const wire = new THREE.MeshBasicMaterial({ color: 0xa9d9e2, wireframe: true, transparent: true, opacity: 0.32 });
    const glow = new THREE.MeshBasicMaterial({ color: 0x77d9eb, transparent: true, opacity: 0.12, blending: THREE.AdditiveBlending });
    const body = new THREE.Mesh(new THREE.TorusGeometry(0.93, 0.045, 10, 80), wire);
    const core = new THREE.Mesh(new THREE.IcosahedronGeometry(0.28, 2), glow);
    const membrane = new THREE.Mesh(new THREE.CircleGeometry(0.76, 72), new THREE.MeshBasicMaterial({ color: 0xbceaf0, transparent: true, opacity: 0.06, side: THREE.DoubleSide }));
    membrane.position.z = -0.03;
    group.add(body, core, membrane);
    return group;
  }

  private loadProductTexture(): void {
    const loader = new THREE.TextureLoader();
    this.textureRequest = loader.load(
      PRODUCT_URI,
      (texture: THREE.Texture) => {
        if (this.disposed) {
          texture.dispose();
          return;
        }
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.minFilter = THREE.LinearMipmapLinearFilter;
        const image = texture.image as { width?: number; height?: number };
        const aspect = (image.width ?? 1) / Math.max(1, image.height ?? 1);
        const displayHeight = 3.82;
        this.productPlane.scale.set(displayHeight * aspect, displayHeight, 1);
        this.productMaterial.map = texture;
        this.productMaterial.needsUpdate = true;
        this.productTexture = texture;
        this.assetReady = true;
        this.fallback.visible = false;
      },
      undefined,
      () => {
        this.assetReady = false;
        this.fallback.visible = true;
      },
    );
  }

  public update(state: DirectedState, elapsed: number): void {
    this.camera.position.copy(state.cameraPosition);
    this.camera.lookAt(state.cameraTarget);

    const revealOpacity = 0.3 + state.reveal * 0.7;
    this.productMaterial.opacity = this.assetReady ? revealOpacity : 0;
    this.fallback.visible = !this.assetReady;
    this.fallback.scale.setScalar(0.88 + state.reveal * 0.18);
    this.fallback.rotation.z = state.resolve * 0.08;

    for (let index = 0; index < this.shards.length; index += 1) {
      const shard = this.shards[index];
      const angle = (index / this.shards.length) * Math.PI * 2;
      const radius = THREE.MathUtils.lerp(2.6, 1.62, state.assembly);
      shard.position.x = 0.42 + Math.cos(angle) * radius;
      shard.position.y = Math.sin(angle) * radius * 0.65;
      shard.rotation.z = THREE.MathUtils.lerp(angle + 0.8, angle + Math.PI * 0.5, state.assembly);
      shard.scale.y = 0.65 + state.assembly * 0.55;
      shard.material.opacity = (0.05 + state.assembly * 0.17) * (1 - state.resolve * 0.72);
    }

    for (let index = 0; index < this.rings.length; index += 1) {
      const ring = this.rings[index];
      const phase = state.resolve > 0.82 ? 0 : Math.sin(elapsed * 0.72 - index * 0.6) * 0.035 * state.membrane;
      ring.scale.setScalar(0.84 + state.membrane * index * 0.07 + phase);
      ring.material.opacity = (0.035 + state.membrane * 0.11) * (1 - state.resolve * 0.58);
      ring.rotation.z = (index % 2 === 0 ? 1 : -1) * state.assembly * 0.06;
    }

    const positions = this.signal.geometry.getAttribute("position") as THREE.BufferAttribute;
    for (let index = 0; index < positions.count; index += 1) {
      const x = positions.getX(index);
      const envelope = Math.exp(-Math.abs(x) * 0.34);
      const wave = Math.sin(x * 4.7 - elapsed * 1.55) * 0.16 * envelope * state.signal * (1 - state.resolve);
      positions.setY(index, wave - 1.18 + state.signal * 0.3);
    }
    positions.needsUpdate = true;
    this.signal.material.opacity = state.signal * (1 - state.resolve) * 0.48;

    const openingX = this.mobile ? 0.7 : 1.0;
    const revealedX = this.mobile ? 0.34 : 0.54;
    const finalShift = this.mobile ? -0.12 : -0.42;
    this.productGroup.position.x = THREE.MathUtils.lerp(openingX, revealedX, state.reveal) + state.resolve * finalShift;
    this.productGroup.position.y = this.mobile ? -0.28 + state.resolve * 0.18 : -0.05;
    this.productGroup.rotation.y = THREE.MathUtils.lerp(-0.19, 0, state.resolve);
    this.root.position.x = state.pointerDriftX * 0.3;
    this.root.position.y = state.pointerDriftY * 0.18;
    this.renderer.render(this.scene, this.camera);
  }

  public resize(width: number, height: number, dpr: number, quality: string): void {
    this.viewportWidth = Math.max(1, width);
    this.viewportHeight = Math.max(1, height);
    this.mobile = this.viewportWidth < 650;
    const dprLimit = quality === "low" ? 1 : quality === "balanced" ? 1.5 : 2;
    this.renderer.setPixelRatio(Math.min(dpr, dprLimit));
    this.renderer.setSize(this.viewportWidth, this.viewportHeight, false);
    this.camera.aspect = this.viewportWidth / this.viewportHeight;
    this.camera.fov = this.mobile ? 39 : 34;
    this.camera.updateProjectionMatrix();
    this.root.scale.setScalar(this.mobile ? 0.92 : 1);
  }

  public dispose(): void {
    this.disposed = true;
    if (this.textureRequest !== null && this.textureRequest !== this.productTexture) this.textureRequest.dispose();
    if (this.productTexture !== null) this.productTexture.dispose();
    this.scene.traverse((object: THREE.Object3D) => {
      const mesh = object as THREE.Mesh;
      if (mesh.geometry instanceof THREE.BufferGeometry) mesh.geometry.dispose();
      const materialValue = mesh.material as THREE.Material | THREE.Material[] | undefined;
      const materials = Array.isArray(materialValue) ? materialValue : materialValue ? [materialValue] : [];
      for (const material of materials) {
        const disposable = material as DisposableMaterial;
        if (disposable.map !== null && disposable.map !== undefined && disposable.map !== this.productTexture) disposable.map.dispose();
        material.dispose();
      }
    });
    this.renderer.dispose();
    this.renderer.forceContextLoss();
  }
}

import { defineExperience, startExperience } from "@signal-lab/experience-sdk";
import { ExperienceDirector } from "./director";
import { AcousticScene } from "./scene";

let scene: AcousticScene | null = null;
let director: ExperienceDirector | null = null;
let interfaceRoot: HTMLElement | null = null;
let currentQuality = "high";

const createInterface = (container: HTMLElement): HTMLElement => {
  const root = document.createElement("main");
  root.className = "echo-page";
  root.setAttribute("aria-label", "澄响智能声音产品发布页");
  root.innerHTML = `
    <div class="ambient-grid" aria-hidden="true"></div>
    <section class="hero" aria-labelledby="hero-title">
      <div class="hero-copy">
        <p class="eyebrow">CLARITY, UNDER YOUR DIRECTION · 01</p>
        <h1 id="hero-title">听见创作<br><span>真正的形状</span></h1>
        <p class="lead">澄响把复杂声场收束成清晰判断。为独立创作者而生的智能声学中枢，让灵感不再消耗于反复试听。</p>
        <a class="primary-action" href="#reserve">申请优先体验 <span aria-hidden="true">↗</span></a>
      </div>
      <p class="scroll-note"><span></span>向下，让信号显形</p>
    </section>
    <section class="capability" aria-labelledby="capability-title">
      <div class="section-index">02 / RESONANCE</div>
      <div class="capability-copy">
        <p class="eyebrow">意图识别 · 空间校准 · 动态成形</p>
        <h2 id="capability-title">不是替你创作，<br>是替你守住每个决定。</h2>
        <p>实时感知人声、环境与叙事重心，澄响将散乱频段聚合为可控声场。你描述情绪，它完成监听校准、层次建议与跨设备一致性。</p>
      </div>
      <ul class="metrics" aria-label="核心能力">
        <li><strong>12 ms</strong><span>意图响应</span></li>
        <li><strong>360°</strong><span>空间感知</span></li>
        <li><strong>1 voice</strong><span>你的审美主导</span></li>
      </ul>
    </section>
    <section class="resolution" id="reserve" aria-labelledby="resolve-title">
      <div class="resolve-copy">
        <p class="eyebrow">THE FIELD IS YOURS · 03</p>
        <h2 id="resolve-title">让声音，终于与你站在同一边。</h2>
        <p>首批创作者体验计划现已开放。带上一个正在发生的作品，听见它更准确的版本。</p>
        <a class="primary-action light" href="mailto:studio@example.invalid?subject=澄响优先体验">加入创作者名单 <span aria-hidden="true">↗</span></a>
      </div>
      <footer><span>澄响 ACOUSTIC INTELLIGENCE</span><span>Designed for independent voices</span></footer>
    </section>
  `;
  container.appendChild(root);
  return root;
};

startExperience(defineExperience({
  mount(context) {
    interfaceRoot = createInterface(context.container);
    director = new ExperienceDirector();
    currentQuality = context.quality;
    try {
      scene = new AcousticScene({
        canvas: context.canvas,
        width: context.viewport.width,
        height: context.viewport.height,
        dpr: context.viewport.dpr,
        quality: context.quality,
        reducedMotion: context.reducedMotion,
      });
      context.canvas.classList.add("acoustic-canvas");
    } catch {
      context.canvas.classList.add("canvas-unavailable");
      scene = null;
    }
  },
  update(frame) {
    if (scene === null || director === null) return;
    const state = director.evaluate({
      progress: frame.progress,
      pointerX: frame.pointer.x,
      pointerY: frame.pointer.y,
      elapsed: frame.elapsed,
      reducedMotion: frame.reducedMotion,
    });
    scene.update(state, frame.elapsed);
    interfaceRoot?.style.setProperty("--story-progress", frame.progress.toFixed(4));
  },
  resize(viewport) {
    scene?.resize(viewport.width, viewport.height, viewport.dpr, currentQuality);
  },
  dispose() {
    scene?.dispose();
    scene = null;
    director = null;
    interfaceRoot?.remove();
    interfaceRoot = null;
  },
}));

:root {
  color-scheme: dark;
  --ink: #eef8f8;
  --muted: #9cafb4;
  --ice: #83dce8;
  --deep: #071017;
  --line: rgba(175, 226, 232, 0.18);
}

* { box-sizing: border-box; }
html { margin: 0; max-width: 100%; background: var(--deep); scroll-behavior: smooth; overflow-x: clip; }
body { margin: 0; min-width: 0; max-width: 100%; background: var(--deep); color: var(--ink); overflow-x: clip; font-family: Inter, "Noto Sans SC", "Microsoft YaHei", sans-serif; }
canvas.acoustic-canvas { position: fixed; inset: 0; width: 100%; height: 100%; max-width: 100%; pointer-events: none; z-index: 1; }
canvas.canvas-unavailable { display: none; }

.echo-page {
  --story-progress: 0;
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 100%;
  min-height: 300vh;
  overflow-x: clip;
  background:
    radial-gradient(circle at 72% 18%, rgba(80, 159, 170, 0.09), transparent 31%),
    linear-gradient(180deg, rgba(7, 16, 23, 0.08), rgba(7, 16, 23, 0.32) 49%, rgba(7, 16, 23, 0.48));
}

.ambient-grid { position: fixed; inset: 0; z-index: -1; opacity: 0.42; pointer-events: none; background-image: linear-gradient(var(--line) 1px, transparent 1px), linear-gradient(90deg, var(--line) 1px, transparent 1px); background-size: min(9vw, 116px) min(9vw, 116px); mask-image: linear-gradient(to bottom, transparent, #000 12%, #000 76%, transparent); }
section { position: relative; width: 100%; max-width: 100%; min-height: 100vh; padding: clamp(28px, 5vw, 76px); }
.hero { display: grid; grid-template-columns: minmax(280px, 0.78fr) 1.22fr; align-items: center; }
.hero-copy { position: relative; z-index: 4; max-width: 650px; padding-left: clamp(0px, 3vw, 42px); }
.eyebrow { margin: 0 0 22px; color: var(--ice); font-size: 11px; font-weight: 650; letter-spacing: 0.22em; text-transform: uppercase; }
h1, h2, p { max-width: 100%; }
h1 { margin: 0; max-height: 42vh; font-size: clamp(44px, 6.6vw, 92px); line-height: 0.99; letter-spacing: -0.065em; font-weight: 580; }
h1 span { color: transparent; -webkit-text-stroke: 1px rgba(224, 246, 248, 0.72); }
.lead { max-width: 480px; margin: 30px 0 28px; color: #b4c3c6; font-size: clamp(14px, 1.2vw, 17px); line-height: 1.85; }
.primary-action { display: inline-flex; min-height: 48px; align-items: center; gap: 38px; padding: 13px 17px; border: 1px solid rgba(143, 222, 231, 0.48); color: var(--ink); text-decoration: none; font-size: 13px; letter-spacing: 0.08em; background: rgba(9, 27, 34, 0.5); backdrop-filter: blur(10px); transition: background .25s ease, color .25s ease; }
.primary-action:hover, .primary-action:focus-visible { background: var(--ice); color: #061217; outline: none; }
.scroll-note { position: absolute; left: clamp(28px, 8vw, 118px); bottom: 28px; display: flex; align-items: center; gap: 12px; color: #74898e; font-size: 10px; letter-spacing: .16em; }
.scroll-note span { width: 36px; height: 1px; background: var(--ice); }

.capability { min-height: 115vh; display: grid; grid-template-columns: .28fr .9fr .48fr; align-items: center; gap: clamp(24px, 5vw, 80px); background: linear-gradient(90deg, rgba(7,16,23,.68), rgba(7,16,23,.1) 48%, rgba(7,16,23,.54)); }
.section-index { align-self: start; padding-top: 20vh; color: #657b80; font-size: 10px; letter-spacing: .19em; writing-mode: vertical-rl; }
.capability-copy { max-width: 610px; }
h2 { margin: 0; font-size: clamp(34px, 4.1vw, 64px); line-height: 1.14; letter-spacing: -.045em; font-weight: 520; }
.capability-copy > p:last-child, .resolve-copy > p { max-width: 510px; margin: 28px 0 0; color: var(--muted); line-height: 1.9; font-size: 15px; }
.metrics { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line); }
.metrics li { display: grid; grid-template-columns: 1fr auto; align-items: baseline; gap: 18px; padding: 22px 0; border-bottom: 1px solid var(--line); }
.metrics strong { color: #dff7f8; font-size: clamp(20px, 2.2vw, 34px); font-weight: 420; }
.metrics span { color: #7f969a; font-size: 11px; letter-spacing: .1em; text-align: right; }

.resolution { min-height: 105vh; display: flex; flex-direction: column; justify-content: flex-end; padding-left: max(52%, 28px); background: linear-gradient(90deg, rgba(7,16,23,.02) 32%, rgba(7,16,23,.35) 55%, rgba(7,16,23,.68) 78%); }
.resolve-copy { position: relative; z-index: 4; max-width: 650px; margin-bottom: clamp(70px, 12vh, 150px); }
.resolve-copy .primary-action { margin-top: 30px; }
.primary-action.light { background: #dff6f6; border-color: #dff6f6; color: #071216; }
.primary-action.light:hover, .primary-action.light:focus-visible { background: var(--ice); }
footer { position: relative; z-index: 4; display: flex; justify-content: space-between; gap: 24px; width: 100%; padding-top: 18px; border-top: 1px solid var(--line); color: #667c81; font-size: 9px; letter-spacing: .13em; text-transform: uppercase; }

@media (max-width: 760px) {
  .echo-page { min-height: 330vh; background: linear-gradient(180deg, rgba(7,16,23,.08), rgba(7,16,23,.32) 55%, rgba(7,16,23,.48)); }
  section { padding: 24px 22px; }
  .ambient-grid { background-size: 72px 72px; opacity: .28; }
  .hero { min-height: 106vh; display: flex; align-items: flex-start; padding-top: max(72px, 10vh); }
  .hero-copy { width: 100%; max-width: 520px; padding-left: 0; }
  .eyebrow { margin-bottom: 17px; font-size: 9px; }
  h1 { max-width: 360px; max-height: 42vh; font-size: clamp(42px, 14.5vw, 62px); line-height: 1.02; }
  .lead { width: min(88%, 390px); margin-top: 22px; font-size: 13px; line-height: 1.72; }
  .primary-action { min-height: 48px; padding: 13px 15px; }
  .scroll-note { left: 22px; bottom: 22px; }
  .capability { min-height: 128vh; display: flex; flex-direction: column; justify-content: flex-end; align-items: stretch; gap: 34px; padding-bottom: 68px; background: linear-gradient(180deg, rgba(7,16,23,.02), rgba(7,16,23,.82) 48%); }
  .section-index { position: absolute; top: 24px; left: 22px; padding: 0; writing-mode: initial; }
  h2 { font-size: clamp(32px, 9.7vw, 48px); }
  .capability-copy > p:last-child, .resolve-copy > p { margin-top: 20px; font-size: 13px; line-height: 1.78; }
